<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetContentHtmlVO;

trait TemplateSnippetContentHtmlAttributeHolder
{
    protected TemplateSnippetContentHtmlVO|string|null $contentHtml = null;
    protected bool $contentHtmlAssigned = false;

    public function getContentHtmlOrCurrent(TemplateSnippetContentHtmlVO $contentHtml): TemplateSnippetContentHtmlVO
    {
        if ($this->contentHtmlAssigned) {
            \assert(null !== $this->contentHtml);
            return TemplateSnippetContentHtmlVO::from($this->contentHtml);
        } else {
            return $contentHtml;
        }
    }
    public function contentHtmlTryBuildInitial(ConstraintFailList $error): ?TemplateSnippetContentHtmlVO
    {
        return  TemplateSnippetContentHtmlVO::tryFrom($this->contentHtmlAssigned ? $this->contentHtml : null, $error);
    }
    public function contentHtml(TemplateSnippetContentHtmlVO|string $contentHtml): static
    {
        $this->contentHtml = $contentHtml;
        $this->contentHtmlAssigned = true;
        return $this;
    }
    public function getContentHtml(): ?string
    {
        return $this->contentHtml instanceof TemplateSnippetContentHtmlVO ? $this->contentHtml->value() : $this->contentHtml;
    }
    public function isContentHtmlAssigned(): bool
    {
        return $this->contentHtmlAssigned;
    }
    public function writeContentHtmlTo(mixed $att): void
    {
        if ($this->contentHtmlAssigned) {
            \assert(null !== $this->contentHtml);
            $att->contentHtml($this->contentHtml);
        }
    }
    public function readContentHtmlFrom(mixed $att): void
    {
        if ($att->isContentHtmlAssigned()) {
            $contentHtml = $att->getContentHtml();
            \assert(null !== $contentHtml);
            $this->contentHtml($contentHtml);
        }
    }
    public function unsetContentHtml(): static
    {
        $this->contentHtmlAssigned = false;
        return $this;
    }
    protected function withDefaultContentHtml(): void
    {
    }
    protected function withAssertedContentHtmlRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->contentHtmlAssigned = $this->contentHtmlAssigned) {
            $value->contentHtml = TemplateSnippetContentHtmlVO::tryFrom($this->contentHtml, $errorsList);
        }
    }
}
